"""Counterexample validation, minimization, and predicate-refinement utilities."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from itertools import product
from typing import Callable, Iterable, Sequence

import z3


@dataclass(frozen=True)
class State:
    """Concrete program state."""

    values: dict[str, int]

    def with_updates(self, **updates: int) -> "State":
        next_values = dict(self.values)
        next_values.update(updates)
        return State(next_values)

    def key(self, var_names: Sequence[str]) -> tuple[int, ...]:
        return tuple(self.values[name] for name in var_names)


@dataclass(frozen=True)
class Transition:
    """Concrete state transition."""

    src: State
    dst: State
    action: str


@dataclass(frozen=True)
class Counterexample:
    """Concrete or abstractly reconstructed counterexample trace."""

    transitions: list[Transition]
    initial_state: State | None = None

    @property
    def length(self) -> int:
        return len(self.transitions)

    def states(self) -> list[State]:
        if self.transitions:
            return [self.transitions[0].src] + [transition.dst for transition in self.transitions]
        if self.initial_state is not None:
            return [self.initial_state]
        return []

    def get_variable_trace(self, var_name: str) -> list[int]:
        return [state.values[var_name] for state in self.states() if var_name in state.values]


@dataclass(frozen=True)
class ValidationResult:
    is_real: bool
    first_spurious_step: int | None


@dataclass(frozen=True)
class CEGARResult:
    safe: bool
    iterations: int
    predicates: list[z3.ExprRef]
    cex: Counterexample | None = None
    original_cex: Counterexample | None = None


@dataclass(frozen=True)
class AbstractGraph:
    members: dict[int, list[State]]
    edges: dict[int, list[int]]
    edge_representatives: dict[tuple[int, int], Transition]
    init_ids: list[int]
    unsafe_ids: set[int]
    unsafe_representatives: dict[int, State]


@dataclass
class FiniteStateSystem:
    """Finite-state transition system used by the lightweight CEGAR loop."""

    name: str
    var_names: tuple[str, ...]
    domains: dict[str, list[int]]
    initial_states: list[State]
    successor_fn: Callable[[State], list[Transition]]
    init_cond: Callable[[State], bool]
    trans_rel: Callable[[State, State], bool]
    safety: Callable[[State], bool]
    initial_predicates: list[z3.ExprRef] = field(default_factory=list)
    candidate_predicates: list[z3.ExprRef] = field(default_factory=list)

    def enumerate_states(self) -> list[State]:
        domain_values = [self.domains[name] for name in self.var_names]
        return [State(dict(zip(self.var_names, values))) for values in product(*domain_values)]

    def successors(self, state: State) -> list[Transition]:
        return self.successor_fn(state)


def _attach_symbolic(concrete_fn, symbolic_fn, system: FiniteStateSystem):
    setattr(concrete_fn, "_symbolic", symbolic_fn)
    setattr(concrete_fn, "_system", system)
    return concrete_fn


def _state_env(var_names: Sequence[str], suffix: str) -> dict[str, z3.IntNumRef]:
    return {name: z3.Int(f"{name}_{suffix}") for name in var_names}


def _substitute_state(predicate: z3.ExprRef, state: State) -> z3.ExprRef:
    substitutions = [(z3.Int(name), z3.IntVal(value)) for name, value in state.values.items()]
    return z3.simplify(z3.substitute(predicate, *substitutions))


def _eval_predicate(predicate: z3.ExprRef, state: State) -> bool:
    result = _substitute_state(predicate, state)
    if z3.is_true(result):
        return True
    if z3.is_false(result):
        return False
    solver = z3.Solver()
    solver.add(z3.Not(result))
    return solver.check() == z3.unsat


def _call_unary(predicate, state: State) -> bool:
    symbolic = getattr(predicate, "_symbolic", None)
    if symbolic is not None:
        solver = z3.Solver()
        env = _state_env(sorted(state.values), "cur")
        solver.add(symbolic(env))
        for name, value in state.values.items():
            solver.add(env[name] == value)
        return solver.check() == z3.sat
    return bool(predicate(state))


def _call_binary(relation, src: State, dst: State) -> bool:
    symbolic = getattr(relation, "_symbolic", None)
    if symbolic is not None:
        solver = z3.Solver()
        current_env = _state_env(sorted(src.values), "cur")
        next_env = _state_env(sorted(dst.values), "nxt")
        solver.add(symbolic(current_env, next_env))
        for name, value in src.values.items():
            solver.add(current_env[name] == value)
        for name, value in dst.values.items():
            solver.add(next_env[name] == value)
        return solver.check() == z3.sat
    return bool(relation(src, dst))


def _dedupe_exprs(predicates: Iterable[z3.ExprRef]) -> list[z3.ExprRef]:
    seen: set[str] = set()
    deduped: list[z3.ExprRef] = []
    for predicate in predicates:
        key = str(z3.simplify(predicate))
        if key in seen:
            continue
        seen.add(key)
        deduped.append(z3.simplify(predicate))
    return deduped


class CEXValidator:
    """Validate whether a counterexample is real under concrete semantics."""

    def validate(self, cex, init_cond, trans_rel, safety) -> ValidationResult:
        states = cex.states()
        if not states:
            return ValidationResult(False, 0)
        if not _call_unary(init_cond, states[0]):
            return ValidationResult(False, 0)
        for index, transition in enumerate(cex.transitions):
            if index > 0 and transition.src.values != cex.transitions[index - 1].dst.values:
                return ValidationResult(False, index)
            if not _call_binary(trans_rel, transition.src, transition.dst):
                return ValidationResult(False, index)
        if _call_unary(safety, states[-1]):
            return ValidationResult(False, len(cex.transitions))
        return ValidationResult(True, None)


class AbstractDomain:
    """Predicate abstraction domain."""

    def __init__(self, var_names: Sequence[str], predicates: Sequence[z3.ExprRef] | None = None):
        self.var_names = list(var_names)
        self.predicates: list[z3.ExprRef] = []
        for predicate in predicates or []:
            self.add_predicate(predicate)

    def abstract_state(self, concrete_state: State) -> tuple[bool, ...]:
        return tuple(_eval_predicate(predicate, concrete_state) for predicate in self.predicates)

    def _implies(self, left: z3.ExprRef, right: z3.ExprRef) -> bool:
        solver = z3.Solver()
        solver.add(left, z3.Not(right))
        return solver.check() == z3.unsat

    def is_subsumed(self, pred_new: z3.ExprRef, pred_existing: z3.ExprRef) -> bool:
        return self._implies(pred_existing, pred_new)

    def add_predicate(self, pred: z3.ExprRef) -> bool:
        predicate = z3.simplify(pred)
        for existing in self.predicates:
            if self.is_subsumed(predicate, existing):
                return False
        self.predicates = [
            existing for existing in self.predicates if not self._implies(predicate, existing)
        ]
        self.predicates.append(predicate)
        return True

    @property
    def predicate_count(self) -> int:
        return len(self.predicates)


class PredicateRefiner:
    """Interpolation-style predicate refiner with a heuristic fallback."""

    def __init__(
        self,
        var_names: Sequence[str],
        candidate_pool: Sequence[z3.ExprRef] | None = None,
        safety=None,
    ) -> None:
        self.var_names = list(var_names)
        self.candidate_pool = list(candidate_pool or [])
        self.safety = safety

    def _separating_candidates(self, left: State, right: State) -> list[z3.ExprRef]:
        candidates: list[z3.ExprRef] = []
        for name in self.var_names:
            left_value = left.values[name]
            right_value = right.values[name]
            var = z3.Int(name)
            if left_value == right_value:
                continue
            candidates.append(var == left_value)
            candidates.append(var == right_value)
            if left_value < right_value:
                candidates.append(var <= left_value)
                candidates.append(var >= right_value)
            else:
                candidates.append(var >= left_value)
                candidates.append(var <= right_value)
        for index, first in enumerate(self.var_names):
            for second in self.var_names[index + 1 :]:
                left_delta = left.values[first] - left.values[second]
                right_delta = right.values[first] - right.values[second]
                if left_delta == right_delta:
                    continue
                expr = z3.Int(first) - z3.Int(second)
                candidates.append(expr == left_delta)
                candidates.append(expr == right_delta)
        return candidates

    def extract_interpolants(self, cex, trans_rel) -> list[z3.ExprRef]:
        """Return separating predicates for a spurious counterexample.

        This Z3 build does not expose the interpolation API, so the implementation
        falls back to predicates that separate the inconsistent states responsible
        for the spurious trace.
        """

        states = cex.states()
        candidates: list[z3.ExprRef] = []

        if len(states) <= 1:
            candidates.extend(self.candidate_pool)
            if states:
                candidates.extend(z3.Int(name) == states[0].values[name] for name in self.var_names)
            return _dedupe_exprs(candidates)

        previous_dst = None
        for index, transition in enumerate(cex.transitions):
            if index > 0 and previous_dst is not None and transition.src.values != previous_dst.values:
                candidates.extend(self._separating_candidates(previous_dst, transition.src))
                break
            if not _call_binary(trans_rel, transition.src, transition.dst):
                candidates.extend(self._separating_candidates(transition.src, transition.dst))
                break
            previous_dst = transition.dst

        if self.safety is not None and _call_unary(self.safety, states[-1]):
            candidates.extend(self._separating_candidates(states[-2], states[-1]))

        if self.candidate_pool:
            if len(states) > 1:
                left = states[0]
                right = states[-1]
                candidates = [
                    predicate
                    for predicate in self.candidate_pool
                    if _eval_predicate(predicate, left) != _eval_predicate(predicate, right)
                ] + candidates
            else:
                candidates = list(self.candidate_pool) + candidates

        if not candidates:
            candidates.extend(z3.Int(name) == states[-1].values[name] for name in self.var_names)
        return _dedupe_exprs(candidates)

    def strengthen_invariant(
        self, current_preds: Sequence[z3.ExprRef], new_interpolants: Sequence[z3.ExprRef]
    ) -> list[z3.ExprRef]:
        domain = AbstractDomain(self.var_names, current_preds)
        for predicate in new_interpolants:
            domain.add_predicate(predicate)
        return list(domain.predicates)

    def minimize_cex(self, cex, trans_rel) -> Counterexample:
        states = cex.states()
        if len(states) <= 2:
            return cex

        minimized: list[Transition] = []
        index = 0
        while index < len(states) - 1:
            jump_to = index + 1
            for candidate in range(len(states) - 1, index, -1):
                if _call_binary(trans_rel, states[index], states[candidate]):
                    jump_to = candidate
                    break
            action = "jump"
            if jump_to == index + 1:
                action = cex.transitions[index].action
            minimized.append(Transition(states[index], states[jump_to], action))
            index = jump_to
        return Counterexample(minimized, initial_state=states[0])


class CEGARLoop:
    """Finite-state predicate-abstraction loop with Z3-backed validation."""

    def __init__(
        self,
        init_cond,
        trans_rel,
        safety,
        max_iterations: int = 20,
        predicate_budget: int = 50,
        *,
        state_space: Sequence[State] | None = None,
        step_fn: Callable[[State], list[Transition]] | None = None,
        candidate_predicates: Sequence[z3.ExprRef] | None = None,
        initial_predicates: Sequence[z3.ExprRef] | None = None,
        name: str = "cegar_system",
        var_names: Sequence[str] | None = None,
    ) -> None:
        system = getattr(trans_rel, "_system", None) or getattr(init_cond, "_system", None)
        self.init_cond = init_cond
        self.trans_rel = trans_rel
        self.safety = safety
        self.max_iterations = max_iterations
        self.predicate_budget = predicate_budget
        self.name = name
        self.system = system

        if system is not None:
            state_space = list(system.enumerate_states())
            step_fn = system.successors
            candidate_predicates = list(candidate_predicates or system.candidate_predicates)
            initial_predicates = list(initial_predicates or system.initial_predicates)
            var_names = system.var_names

        if state_space is None or step_fn is None:
            raise ValueError("CEGARLoop requires a finite state space and successor function")

        self.state_space = list(state_space)
        self.step_fn = step_fn
        self.var_names = list(var_names or sorted(self.state_space[0].values))
        self.validator = CEXValidator()
        self.domain = AbstractDomain(self.var_names, initial_predicates or [])
        self.refiner = PredicateRefiner(
            self.var_names, candidate_predicates or [], safety=self.safety
        )

    def _build_abstract_graph(self) -> AbstractGraph:
        members: dict[int, list[State]] = defaultdict(list)
        edges: dict[int, list[int]] = defaultdict(list)
        edge_representatives: dict[tuple[int, int], Transition] = {}
        init_ids: list[int] = []
        unsafe_ids: set[int] = set()
        unsafe_representatives: dict[int, State] = {}

        signature_to_id: dict[tuple[bool, ...], int] = {}

        def get_id(signature: tuple[bool, ...]) -> int:
            if signature not in signature_to_id:
                signature_to_id[signature] = len(signature_to_id)
            return signature_to_id[signature]

        for state in self.state_space:
            signature = self.domain.abstract_state(state)
            abstract_id = get_id(signature)
            members[abstract_id].append(state)
            if _call_unary(self.init_cond, state) and abstract_id not in init_ids:
                init_ids.append(abstract_id)
            if not _call_unary(self.safety, state):
                unsafe_ids.add(abstract_id)
                unsafe_representatives.setdefault(abstract_id, state)

        for state in self.state_space:
            src_id = get_id(self.domain.abstract_state(state))
            for transition in self.step_fn(state):
                dst_id = get_id(self.domain.abstract_state(transition.dst))
                if dst_id not in edges[src_id]:
                    edges[src_id].append(dst_id)
                    edge_representatives[(src_id, dst_id)] = transition

        return AbstractGraph(
            members=dict(members),
            edges=dict(edges),
            edge_representatives=edge_representatives,
            init_ids=init_ids,
            unsafe_ids=unsafe_ids,
            unsafe_representatives=unsafe_representatives,
        )

    def _verify_abstract_graph(self, graph: AbstractGraph) -> bool:
        fp = z3.Fixedpoint()
        fp.set(engine="spacer")
        reach = z3.Function(f"{self.name}_Reach", z3.IntSort(), z3.BoolSort())
        edge = z3.Function(f"{self.name}_Edge", z3.IntSort(), z3.IntSort(), z3.BoolSort())
        bad = z3.Function(f"{self.name}_Bad", z3.IntSort(), z3.BoolSort())
        error = z3.Function(f"{self.name}_Error", z3.BoolSort())
        src, dst = z3.Ints(f"{self.name}_src {self.name}_dst")
        fp.register_relation(reach, edge, bad, error)
        fp.declare_var(src, dst)
        fp.rule(reach(dst), [reach(src), edge(src, dst)])
        fp.rule(error(), [reach(src), bad(src)])
        for init_id in graph.init_ids:
            fp.fact(reach(z3.IntVal(init_id)))
        for src_id, dst_ids in graph.edges.items():
            for dst_id in dst_ids:
                fp.fact(edge(z3.IntVal(src_id), z3.IntVal(dst_id)))
        for bad_id in graph.unsafe_ids:
            fp.fact(bad(z3.IntVal(bad_id)))
        return fp.query(error()) == z3.unsat

    def _find_abstract_path(self, graph: AbstractGraph) -> list[int]:
        if not graph.unsafe_ids:
            return []

        def dfs(node: int, path: list[int], seen: set[int]) -> list[int] | None:
            if node in graph.unsafe_ids:
                return path
            for successor in graph.edges.get(node, []):
                if successor in seen:
                    continue
                result = dfs(successor, path + [successor], seen | {successor})
                if result is not None:
                    return result
            return None

        for init_id in graph.init_ids:
            if init_id in graph.unsafe_ids:
                return [init_id]
            result = dfs(init_id, [init_id], {init_id})
            if result is not None:
                return result
        return []

    def _reconstruct_counterexample(self, graph: AbstractGraph, path: list[int]) -> Counterexample:
        if not path:
            return Counterexample([])
        if len(path) == 1:
            state = graph.unsafe_representatives.get(path[0], graph.members[path[0]][0])
            return Counterexample([], initial_state=state)
        transitions = [
            graph.edge_representatives[(path[index], path[index + 1])]
            for index in range(len(path) - 1)
        ]
        return Counterexample(transitions, initial_state=transitions[0].src)

    def run(self) -> CEGARResult:
        iterations = 0
        while iterations < self.max_iterations and self.domain.predicate_count <= self.predicate_budget:
            iterations += 1
            graph = self._build_abstract_graph()
            if self._verify_abstract_graph(graph):
                return CEGARResult(True, iterations, list(self.domain.predicates))

            abstract_path = self._find_abstract_path(graph)
            cex = self._reconstruct_counterexample(graph, abstract_path)
            validation = self.validator.validate(cex, self.init_cond, self.trans_rel, self.safety)
            if validation.is_real:
                minimized = self.refiner.minimize_cex(cex, self.trans_rel)
                return CEGARResult(
                    False,
                    iterations,
                    list(self.domain.predicates),
                    cex=minimized,
                    original_cex=cex,
                )

            for predicate in self.refiner.extract_interpolants(cex, self.trans_rel):
                if self.domain.add_predicate(predicate):
                    break
            else:
                break
        return CEGARResult(False, iterations, list(self.domain.predicates), cex=None)


def _make_state(**values: int) -> State:
    return State(values)


def build_off_by_one_system() -> FiniteStateSystem:
    var_names = ("x",)
    initial_states = [_make_state(x=0)]

    def successors(state: State) -> list[Transition]:
        x = state.values["x"]
        next_x = x + 1 if x < 4 else x
        return [Transition(state, _make_state(x=next_x), "inc" if x < 4 else "hold")]

    def init(state: State) -> bool:
        return state.values["x"] == 0

    def trans(src: State, dst: State) -> bool:
        x = src.values["x"]
        xp = dst.values["x"]
        return (x < 4 and xp == x + 1) or (x >= 4 and xp == x)

    def safety(state: State) -> bool:
        return state.values["x"] <= 4

    system = FiniteStateSystem(
        name="off_by_one",
        var_names=var_names,
        domains={"x": [0, 1, 2, 3, 4, 5]},
        initial_states=initial_states,
        successor_fn=successors,
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        candidate_predicates=[z3.Int("x") <= 4],
    )
    system.init_cond = _attach_symbolic(init, lambda cur: cur["x"] == 0, system)
    system.trans_rel = _attach_symbolic(
        trans,
        lambda cur, nxt: z3.Or(
            z3.And(cur["x"] < 4, nxt["x"] == cur["x"] + 1),
            z3.And(cur["x"] >= 4, nxt["x"] == cur["x"]),
        ),
        system,
    )
    system.safety = _attach_symbolic(safety, lambda cur: cur["x"] <= 4, system)
    return system


def build_double_counter_system() -> FiniteStateSystem:
    var_names = ("x", "y")
    initial_states = [_make_state(x=0, y=0)]

    def successors(state: State) -> list[Transition]:
        x = state.values["x"]
        y = state.values["y"]
        next_state = _make_state(x=min(x + 1, 3), y=min(y + 2, 6))
        return [Transition(state, next_state, "tick")]

    def init(state: State) -> bool:
        return state.values == {"x": 0, "y": 0}

    def trans(src: State, dst: State) -> bool:
        return dst.values["x"] == min(src.values["x"] + 1, 3) and dst.values["y"] == min(
            src.values["y"] + 2, 6
        )

    def safety(state: State) -> bool:
        return state.values["x"] + state.values["y"] < 7

    system = FiniteStateSystem(
        name="double_counter",
        var_names=var_names,
        domains={"x": [0, 1, 2, 3], "y": [0, 2, 4, 6]},
        initial_states=initial_states,
        successor_fn=successors,
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        initial_predicates=[
            z3.Int("x") == 0,
            z3.Int("x") == 1,
            z3.Int("x") == 2,
            z3.Int("x") == 3,
            z3.Int("y") == 0,
            z3.Int("y") == 2,
            z3.Int("y") == 4,
            z3.Int("y") == 6,
        ],
    )
    system.init_cond = _attach_symbolic(
        init, lambda cur: z3.And(cur["x"] == 0, cur["y"] == 0), system
    )
    system.trans_rel = _attach_symbolic(
        trans,
        lambda cur, nxt: z3.And(
            nxt["x"] == z3.If(cur["x"] < 3, cur["x"] + 1, 3),
            nxt["y"] == z3.If(cur["y"] < 6, cur["y"] + 2, 6),
        ),
        system,
    )
    system.safety = _attach_symbolic(safety, lambda cur: cur["x"] + cur["y"] < 7, system)
    return system


def build_array_bounds_system() -> FiniteStateSystem:
    var_names = ("idx", "phase", "len")
    initial_states = [_make_state(idx=0, phase=0, len=3)]

    def successors(state: State) -> list[Transition]:
        idx = state.values["idx"]
        phase = state.values["phase"]
        length = state.values["len"]
        if phase < 2:
            return [
                Transition(
                    state,
                    _make_state(idx=min(idx + 1, 3), phase=phase + 1, len=length),
                    "advance",
                )
            ]
        if phase == 2:
            return [Transition(state, _make_state(idx=idx, phase=3, len=length), "settle")]
        return [Transition(state, state, "hold")]

    def init(state: State) -> bool:
        return state.values == {"idx": 0, "phase": 0, "len": 3}

    def trans(src: State, dst: State) -> bool:
        idx = src.values["idx"]
        phase = src.values["phase"]
        length = src.values["len"]
        if phase < 2:
            return dst.values == {"idx": min(idx + 1, 3), "phase": phase + 1, "len": length}
        if phase == 2:
            return dst.values == {"idx": idx, "phase": 3, "len": length}
        return dst.values == src.values

    def safety(state: State) -> bool:
        return state.values["idx"] >= 0 and state.values["idx"] < state.values["len"] and state.values["len"] == 3

    system = FiniteStateSystem(
        name="array_bounds",
        var_names=var_names,
        domains={"idx": [0, 1, 2, 3], "phase": [0, 1, 2, 3], "len": [2, 3]},
        initial_states=initial_states,
        successor_fn=successors,
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        candidate_predicates=[
            z3.Int("len") == 3,
            z3.Int("idx") <= 2,
            z3.Int("phase") >= z3.Int("idx"),
        ],
    )
    system.init_cond = _attach_symbolic(
        init,
        lambda cur: z3.And(cur["idx"] == 0, cur["phase"] == 0, cur["len"] == 3),
        system,
    )
    system.trans_rel = _attach_symbolic(
        trans,
        lambda cur, nxt: z3.Or(
            z3.And(
                cur["phase"] < 2,
                nxt["idx"] == z3.If(cur["idx"] < 3, cur["idx"] + 1, 3),
                nxt["phase"] == cur["phase"] + 1,
                nxt["len"] == cur["len"],
            ),
            z3.And(
                cur["phase"] == 2,
                nxt["idx"] == cur["idx"],
                nxt["phase"] == 3,
                nxt["len"] == cur["len"],
            ),
            z3.And(
                cur["phase"] >= 3,
                nxt["idx"] == cur["idx"],
                nxt["phase"] == cur["phase"],
                nxt["len"] == cur["len"],
            ),
        ),
        system,
    )
    system.safety = _attach_symbolic(
        safety,
        lambda cur: z3.And(cur["idx"] >= 0, cur["idx"] < cur["len"], cur["len"] == 3),
        system,
    )
    return system


def build_nonnegative_loop_system() -> FiniteStateSystem:
    var_names = ("x",)
    initial_states = [_make_state(x=0)]

    def successors(state: State) -> list[Transition]:
        x = state.values["x"]
        next_state = _make_state(x=min(x + 1, 4))
        return [Transition(state, next_state, "step")]

    def init(state: State) -> bool:
        return state.values["x"] == 0

    def trans(src: State, dst: State) -> bool:
        return dst.values["x"] == min(src.values["x"] + 1, 4)

    def safety(state: State) -> bool:
        return state.values["x"] >= 0

    system = FiniteStateSystem(
        name="nonnegative_loop",
        var_names=var_names,
        domains={"x": [0, 1, 2, 3, 4]},
        initial_states=initial_states,
        successor_fn=successors,
        init_cond=init,
        trans_rel=trans,
        safety=safety,
    )
    system.init_cond = _attach_symbolic(init, lambda cur: cur["x"] == 0, system)
    system.trans_rel = _attach_symbolic(
        trans, lambda cur, nxt: nxt["x"] == z3.If(cur["x"] < 4, cur["x"] + 1, 4), system
    )
    system.safety = _attach_symbolic(safety, lambda cur: cur["x"] >= 0, system)
    return system


def build_producer_consumer_system() -> FiniteStateSystem:
    var_names = ("buf",)
    initial_states = [_make_state(buf=0)]

    def successors(state: State) -> list[Transition]:
        buf = state.values["buf"]
        transitions: list[Transition] = []
        if buf == 0:
            transitions.append(Transition(state, _make_state(buf=1), "produce"))
        elif buf == 1:
            transitions.append(Transition(state, _make_state(buf=2), "produce"))
            transitions.append(Transition(state, _make_state(buf=4), "burst_overflow"))
        elif buf == 2:
            transitions.append(Transition(state, _make_state(buf=3), "produce"))
            transitions.append(Transition(state, _make_state(buf=4), "burst"))
        elif buf == 3:
            transitions.append(Transition(state, _make_state(buf=4), "produce"))
        else:
            transitions.append(Transition(state, state, "hold"))
        return transitions

    def init(state: State) -> bool:
        return state.values["buf"] == 0

    def trans(src: State, dst: State) -> bool:
        src_buf = src.values["buf"]
        dst_buf = dst.values["buf"]
        return (
            (src_buf == 0 and dst_buf == 1)
            or (src_buf == 1 and dst_buf in {2, 4})
            or (src_buf == 2 and dst_buf in {3, 4})
            or (src_buf == 3 and dst_buf == 4)
            or (src_buf >= 4 and dst_buf == src_buf)
        )

    def safety(state: State) -> bool:
        return state.values["buf"] <= 3

    system = FiniteStateSystem(
        name="producer_consumer",
        var_names=var_names,
        domains={"buf": [0, 1, 2, 3, 4]},
        initial_states=initial_states,
        successor_fn=successors,
        init_cond=init,
        trans_rel=trans,
        safety=safety,
        initial_predicates=[
            z3.Int("buf") == 0,
            z3.Int("buf") == 1,
            z3.Int("buf") == 2,
            z3.Int("buf") == 3,
        ],
    )
    system.init_cond = _attach_symbolic(init, lambda cur: cur["buf"] == 0, system)
    system.trans_rel = _attach_symbolic(
        trans,
        lambda cur, nxt: z3.Or(
            z3.And(cur["buf"] == 0, nxt["buf"] == 1),
            z3.And(cur["buf"] == 1, z3.Or(nxt["buf"] == 2, nxt["buf"] == 4)),
            z3.And(cur["buf"] == 2, z3.Or(nxt["buf"] == 3, nxt["buf"] == 4)),
            z3.And(cur["buf"] == 3, nxt["buf"] == 4),
            z3.And(cur["buf"] >= 4, nxt["buf"] == cur["buf"]),
        ),
        system,
    )
    system.safety = _attach_symbolic(safety, lambda cur: cur["buf"] <= 3, system)
    return system


